    ok(b.js("document.querySelector('.page-tools button.lock-link.open') !== null") and b.js("document.querySelector('form#lock-form') !== null") and "reveal" not in b.js("location.search"), "[lock] after entering the password the lock shows open, on the plain gallery address", b.js("location.href"))
    shot(b, "01c-lock-open")
