        pv = b.js("({bar: (document.getElementById('link-preview') || {}).innerText || '', tools: document.querySelectorAll('.priv-toggle, .cover-toggle, .edit-toggle, .page-share').length, owner: typeof ownerState !== 'undefined' && ownerState !== null, sticky: getComputedStyle(document.getElementById('link-preview')).position})")
