        b.goto(BL + "/", 1.2)
        ok("Rome" in b.js("document.body.innerText") and "Pisa" not in b.js("document.body.innerText"), "[preview] the front page shows what the link covers (Rome) and nothing hinting at the rest")
        b.js("document.querySelector('.lp-more').click()"); b.drain(0.3)
        pl = b.js("(() => { const p = document.getElementById('lp-panel'); const r = p.getBoundingClientRect(); return {shown: !p.hidden, text: p.innerText, inside: r.left >= 0 && r.right <= innerWidth}; })()")
        ok(pl["shown"] and pl["inside"] and "Rome and everything inside it" in pl["text"] and "not shown and not hinted at" in pl["text"] and "Original downloads are off" in pl["text"], "[preview] What's included lists what the link shows and what it doesn't", pl["text"][:200])
        shot(b, "35-preview-included")
        b.viewport(390, 844, mobile=True); b.goto(BL + "/?folder=Rome", 1.2); b.js("document.querySelector('.lp-more').click()"); b.drain(0.3)
        ok(b.js(overflow) and b.js("document.getElementById('lp-panel').getBoundingClientRect().right <= innerWidth"), "[preview] on a phone the strip and its list fit the screen")
